import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_01_package_boundary.png",o="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_02_lifecycle_state.png",i="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_03_shared_astar_flow.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_04_three_plugins.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_05_support_components.png",p="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_06_result_states.png",f=JSON.parse('{"title":"一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流","description":"nav2smacplanner 不是单一 Planner，而是一套模板化规划框架：Planner Server 管理 ROS 接口，三个 GlobalPlanner 插件共享 AStarAlgorithm<NodeT，不同 Node 类型决定状态空间、运动扩展、启发函数和碰撞语义。","frontmatter":{"title":"一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流","description":"nav2smacplanner 不是单一 Planner，而是一套模板化规划框架：Planner Server 管理 ROS 接口，三个 GlobalPlanner 插件共享 AStarAlgorithm<NodeT，不同 Node 类型决定状态空间、运动扩展、启发函数和碰撞语义。","date":"2026-07-21","topic":"Nav2 工程实践","section":"二 · 全局规划与路径搜索","readingTime":6,"source":"2026-07-21/nav2_smac_planner_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-21/nav2_smac_planner_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-smac-planner-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流"}],["meta",{"property":"og:description","content":"nav2smacplanner 不是单一 Planner，而是一套模板化规划框架：Planner Server 管理 ROS 接口，三个 GlobalPlanner 插件共享 AStarAlgorithm<NodeT，不同 Node 类型决定状态空间、运动扩展、启发函数和碰撞语义。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-smac-planner-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流"}],["meta",{"name":"twitter:description","content":"nav2smacplanner 不是单一 Planner，而是一套模板化规划框架：Planner Server 管理 ROS 接口，三个 GlobalPlanner 插件共享 AStarAlgorithm<NodeT，不同 Node 类型决定状态空间、运动扩展、启发函数和碰撞语义。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_smac_planner_01_package_boundary.png"}]],"prev":{"text":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D","link":"/nav2/nav2-costmap-first-navfn-smac2d-tuning"},"next":{"text":"一条参数命令，如何让 Nav2 当场“换脑”？逐行拆解 PlannerServer 动态回调","link":"/nav2/nav2-planner-dynamic-parameters-callback"}},"headers":[],"relativePath":"nav2/nav2-smac-planner-full-dataflow.md","filePath":"nav2/nav2-smac-planner-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-smac-planner-full-dataflow.md"};function d(m,a,_,u,b,v){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="一颗-a-大脑-三种机器人怎么共用-拆解-nav2-smac-planner-全调用、状态与数据流" tabindex="-1">一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流 <a class="header-anchor" href="#一颗-a-大脑-三种机器人怎么共用-拆解-nav2-smac-planner-全调用、状态与数据流" aria-label="Permalink to &quot;一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流&quot;">​</a></h1><p><code>nav2_smac_planner</code> 不是单一 Planner，而是一套模板化规划框架：Planner Server 管理 ROS 接口，三个 GlobalPlanner 插件共享 <code>AStarAlgorithm&lt;NodeT&gt;</code>，不同 Node 类型决定状态空间、运动扩展、启发函数和碰撞语义。</p><h2 id="一、包边界与插件入口" tabindex="-1">一、包边界与插件入口 <a class="header-anchor" href="#一、包边界与插件入口" aria-label="Permalink to &quot;一、包边界与插件入口&quot;">​</a></h2><h3 id="_1-1-ros-接口全部在-planner-server" tabindex="-1">1.1 ROS 接口全部在 Planner Server <a class="header-anchor" href="#_1-1-ros-接口全部在-planner-server" aria-label="Permalink to &quot;1.1 ROS 接口全部在 Planner Server&quot;">​</a></h3><p>本包不创建独立节点。<code>ComputePathToPose</code> 或 <code>ComputePathThroughPoses</code> Action 进入 Planner Server，服务器完成起终点 TF、插件选择、Costmap 管理与 Action Result；Smac 插件只实现进程内 <code>configure()</code>、<code>activate()</code>、<code>createPlan()</code> 等接口。</p><h3 id="_1-2-三个插件对应三种状态空间" tabindex="-1">1.2 三个插件对应三种状态空间 <a class="header-anchor" href="#_1-2-三个插件对应三种状态空间" aria-label="Permalink to &quot;1.2 三个插件对应三种状态空间&quot;">​</a></h3><ul><li><code>SmacPlanner2D</code>：状态为 <code>x、y</code>，使用八连通栅格。</li><li><code>SmacPlannerHybrid</code>：状态为 <code>x、y、theta</code>，在线生成 Dubin 或 Reeds-Shepp 邻居。</li><li><code>SmacPlannerLattice</code>：状态同样包含离散朝向，但邻居来自 JSON 运动基元。</li></ul><p><img src="'+l+'" alt="Smac Planner 包边界"></p><h2 id="二、lifecycle-决定资源是否可用" tabindex="-1">二、Lifecycle 决定资源是否可用 <a class="header-anchor" href="#二、lifecycle-决定资源是否可用" aria-label="Permalink to &quot;二、Lifecycle 决定资源是否可用&quot;">​</a></h2><h3 id="_2-1-configure-创建算法对象" tabindex="-1">2.1 configure 创建算法对象 <a class="header-anchor" href="#_2-1-configure-创建算法对象" aria-label="Permalink to &quot;2.1 configure 创建算法对象&quot;">​</a></h3><p>Planner Server 在 configure 阶段通过 pluginlib 创建插件，并传入父 Lifecycle Node、TF Buffer 和 Global Costmap。插件读取参数，创建 A*、碰撞检查器、可选 CostmapDownsampler、Smoother 与调试 Publisher。</p><h3 id="_2-2-active-状态才开放运行入口" tabindex="-1">2.2 active 状态才开放运行入口 <a class="header-anchor" href="#_2-2-active-状态才开放运行入口" aria-label="Permalink to &quot;2.2 active 状态才开放运行入口&quot;">​</a></h3><p><code>activate()</code> 激活 Publisher 和动态参数回调；<code>deactivate()</code> 关闭运行期入口；<code>cleanup()</code> 释放搜索、平滑和地图资源。插件不是 Lifecycle Node，但资源状态跟随 Planner Server。</p><p><img src="'+o+'" alt="Smac Planner Lifecycle 与资源状态"></p><h2 id="三、一次-createplan-怎样运行" tabindex="-1">三、一次 createPlan 怎样运行 <a class="header-anchor" href="#三、一次-createplan-怎样运行" aria-label="Permalink to &quot;三、一次 createPlan 怎样运行&quot;">​</a></h2><h3 id="_3-1-输入被离散成搜索状态" tabindex="-1">3.1 输入被离散成搜索状态 <a class="header-anchor" href="#_3-1-输入被离散成搜索状态" aria-label="Permalink to &quot;3.1 输入被离散成搜索状态&quot;">​</a></h3><p>插件锁定自身状态和 Costmap。若启用降采样，先生成低分辨率 Costmap；随后把世界坐标中的起点、终点转换成栅格索引和可选离散朝向，并检查边界与碰撞。</p><p>起终点落在同一离散状态时可直接返回；否则进入共享 A*。</p><h3 id="_3-2-astaralgorithm-管理公共搜索循环" tabindex="-1">3.2 AStarAlgorithm 管理公共搜索循环 <a class="header-anchor" href="#_3-2-astaralgorithm-管理公共搜索循环" aria-label="Permalink to &quot;3.2 AStarAlgorithm 管理公共搜索循环&quot;">​</a></h3><p>Open Queue 保存待展开节点，Visited 状态防止重复搜索，<code>getTraversalCost()</code> 计算移动代价，启发函数估计到目标的剩余成本。松弛成功后更新 <code>accumulated_cost</code> 与 parent，直到精确到达、容差内找到最佳近似节点、取消或耗尽迭代。</p><p><code>NodeT</code> 决定邻居怎样产生、状态怎样索引和 Costmap 代价如何进入边成本，因此三套 Planner 能共享循环而保持不同运动学。</p><p><img src="'+i+'" alt="共享模板 A* 调用流程"></p><h2 id="四、三种-planner-真正差在哪里" tabindex="-1">四、三种 Planner 真正差在哪里 <a class="header-anchor" href="#四、三种-planner-真正差在哪里" aria-label="Permalink to &quot;四、三种 Planner 真正差在哪里&quot;">​</a></h2><h3 id="_4-1-smacplanner2d-面向二维通行性" tabindex="-1">4.1 SmacPlanner2D 面向二维通行性 <a class="header-anchor" href="#_4-1-smacplanner2d-面向二维通行性" aria-label="Permalink to &quot;4.1 SmacPlanner2D 面向二维通行性&quot;">​</a></h3><p>它在八邻域栅格中移动，启发函数使用二维距离，Costmap 代价通过 <code>cost_travel_multiplier</code> 进入移动成本。它不维护车辆朝向和最小转弯半径，适合圆形、全向或允许控制器后续修正姿态的机器人。</p><h3 id="_4-2-hybrid-a-把运动学写进搜索" tabindex="-1">4.2 Hybrid-A* 把运动学写进搜索 <a class="header-anchor" href="#_4-2-hybrid-a-把运动学写进搜索" aria-label="Permalink to &quot;4.2 Hybrid-A* 把运动学写进搜索&quot;">​</a></h3><p>Hybrid 状态包含离散 heading，邻居来自运动模型，碰撞检查覆盖完整 SE2 footprint。障碍启发与运动学启发共同工作，解析扩展会尝试用连续曲线直连目标。使用 Reeds-Shepp 时可以倒车。</p><h3 id="_4-3-state-lattice-用运动基元定义动作" tabindex="-1">4.3 State Lattice 用运动基元定义动作 <a class="header-anchor" href="#_4-3-state-lattice-用运动基元定义动作" aria-label="Permalink to &quot;4.3 State Lattice 用运动基元定义动作&quot;">​</a></h3><p>Lattice 从 JSON metadata 读取分辨率、朝向数量和 motion primitives。每个基元包含完整局部轨迹，能表达特定底盘可执行的转向、前进或倒车动作，但基元必须与机器人模型和 Costmap 分辨率匹配。</p><p><img src="'+c+'" alt="Smac 三插件状态空间对比"></p><h2 id="五、搜索之外还有五个关键组件" tabindex="-1">五、搜索之外还有五个关键组件 <a class="header-anchor" href="#五、搜索之外还有五个关键组件" aria-label="Permalink to &quot;五、搜索之外还有五个关键组件&quot;">​</a></h2><h3 id="_5-1-costmapdownsampler" tabindex="-1">5.1 CostmapDownsampler <a class="header-anchor" href="#_5-1-costmapdownsampler" aria-label="Permalink to &quot;5.1 CostmapDownsampler&quot;">​</a></h3><p>降低搜索网格分辨率以换取速度，但可能损失窄门和细障碍信息。</p><h3 id="_5-2-gridcollisionchecker" tabindex="-1">5.2 GridCollisionChecker <a class="header-anchor" href="#_5-2-gridcollisionchecker" aria-label="Permalink to &quot;5.2 GridCollisionChecker&quot;">​</a></h3><p>统一检查栅格状态或 SE2 footprint 是否越界、未知或碰撞。机器人几何配置错误会让三种搜索同时失真。</p><h3 id="_5-3-障碍启发缓存" tabindex="-1">5.3 障碍启发缓存 <a class="header-anchor" href="#_5-3-障碍启发缓存" aria-label="Permalink to &quot;5.3 障碍启发缓存&quot;">​</a></h3><p>Hybrid 与 Lattice 可缓存从目标传播的障碍启发，减少重复规划开销；地图或目标变化时必须正确失效。</p><h3 id="_5-4-analyticexpansion" tabindex="-1">5.4 AnalyticExpansion <a class="header-anchor" href="#_5-4-analyticexpansion" aria-label="Permalink to &quot;5.4 AnalyticExpansion&quot;">​</a></h3><p>非完整约束搜索在接近目标时尝试连续曲线直达，成功可减少离散搜索尾部扩展。</p><h3 id="_5-5-smoother" tabindex="-1">5.5 Smoother <a class="header-anchor" href="#_5-5-smoother" aria-label="Permalink to &quot;5.5 Smoother&quot;">​</a></h3><p>搜索完成后在剩余时间内优化路径。平滑失败不必然等于规划失败，原始可行 Path 仍可能返回。</p><p><img src="'+s+'" alt="Smac Planner 支撑组件"></p><h2 id="六、路径如何返回-action" tabindex="-1">六、路径如何返回 Action <a class="header-anchor" href="#六、路径如何返回-action" aria-label="Permalink to &quot;六、路径如何返回 Action&quot;">​</a></h2><h3 id="_6-1-parent-链回溯并还原坐标" tabindex="-1">6.1 parent 链回溯并还原坐标 <a class="header-anchor" href="#_6-1-parent-链回溯并还原坐标" aria-label="Permalink to &quot;6.1 parent 链回溯并还原坐标&quot;">​</a></h3><p>A* 从终态沿 parent 回到起点，插件把离散状态还原为世界坐标 Pose。2D 根据路径方向补充 yaw；Hybrid 与 Lattice 保留搜索状态中的朝向，Lattice 还会清理重复 Pose。</p><p>原始结果可发布到 <code>unsmoothed_plan</code>，降采样地图也可单独观察；平滑后的 Path 作为函数返回值交还 Planner Server。</p><h3 id="_6-2-结果不只有成功和失败" tabindex="-1">6.2 结果不只有成功和失败 <a class="header-anchor" href="#_6-2-结果不只有成功和失败" aria-label="Permalink to &quot;6.2 结果不只有成功和失败&quot;">​</a></h3><ul><li>起终点同状态：直接成功。</li><li>精确到达：回溯目标节点。</li><li>容差成功：回溯搜索到的最佳近似节点。</li><li>无解或超时：返回空 Path 或抛规划异常。</li><li>输入越界、碰撞或 TF 错误：由 Planner Server 转为 Action 失败。</li></ul><p><img src="'+p+`" alt="createPlan 的结果状态"></p><h2 id="七、动态参数与跨周期状态" tabindex="-1">七、动态参数与跨周期状态 <a class="header-anchor" href="#七、动态参数与跨周期状态" aria-label="Permalink to &quot;七、动态参数与跨周期状态&quot;">​</a></h2><h3 id="_7-1-参数变化可能重建对象" tabindex="-1">7.1 参数变化可能重建对象 <a class="header-anchor" href="#_7-1-参数变化可能重建对象" aria-label="Permalink to &quot;7.1 参数变化可能重建对象&quot;">​</a></h3><p>搜索模型、角度量化、降采样和 Smoother 相关参数不是简单改一个数，部分变化会重建 A*、碰撞检查器或降采样资源。动态回调只在 active 状态存在，并与规划调用互斥。</p><h3 id="_7-2-可复用状态用于提速" tabindex="-1">7.2 可复用状态用于提速 <a class="header-anchor" href="#_7-2-可复用状态用于提速" aria-label="Permalink to &quot;7.2 可复用状态用于提速&quot;">​</a></h3><p>插件会复用启发缓存、搜索节点存储、Smoother 和 CostmapDownsampler。缓存能降低重复规划时间，也意味着地图尺寸、分辨率、目标或运动模型变化时必须正确刷新。</p><h2 id="八、选择与排障" tabindex="-1">八、选择与排障 <a class="header-anchor" href="#八、选择与排障" aria-label="Permalink to &quot;八、选择与排障&quot;">​</a></h2><h3 id="_8-1-选择依据是机器人可执行性" tabindex="-1">8.1 选择依据是机器人可执行性 <a class="header-anchor" href="#_8-1-选择依据是机器人可执行性" aria-label="Permalink to &quot;8.1 选择依据是机器人可执行性&quot;">​</a></h3><p>只需要二维可通行路径时选择 Smac2D；需要朝向、最小转弯半径和可选倒车时选择 Hybrid；需要用预生成动作精确约束特殊底盘时选择 Lattice。路径看起来更圆滑不是唯一标准，还要验证控制器能否跟踪和真实 footprint 是否安全。</p><h3 id="_8-2-按边界定位问题" tabindex="-1">8.2 按边界定位问题 <a class="header-anchor" href="#_8-2-按边界定位问题" aria-label="Permalink to &quot;8.2 按边界定位问题&quot;">​</a></h3><ul><li>收不到请求：检查 Planner Server 与 Action。</li><li>起终点 frame 错：检查服务器侧 TF。</li><li>三插件都失败：检查 Global Costmap、footprint 与输入合法性。</li><li>只有某插件失败：检查状态空间、运动模型、基元或专属参数。</li><li>Path 已生成但执行失败：进入 Controller Server 与 Local Costmap，不再归因于 Smac。</li></ul><h2 id="九、总结与参考" tabindex="-1">九、总结与参考 <a class="header-anchor" href="#九、总结与参考" aria-label="Permalink to &quot;九、总结与参考&quot;">​</a></h2><h3 id="_9-1-一条主线理解整个包" tabindex="-1">9.1 一条主线理解整个包 <a class="header-anchor" href="#_9-1-一条主线理解整个包" aria-label="Permalink to &quot;9.1 一条主线理解整个包&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Planner Action → Planner Server → Smac 插件</span></span>
<span class="line"><span>→ Costmap／碰撞检查 → AStarAlgorithm&lt;NodeT&gt;</span></span>
<span class="line"><span>→ parent 回溯 → 可选平滑 → Path → Action Result</span></span></code></pre></div><p>共享 A* 负责“怎样搜索”，Node2D、NodeHybrid 与 NodeLattice 负责“机器人允许怎样移动”。</p><h3 id="_9-2-官方参考" tabindex="-1">9.2 官方参考 <a class="header-anchor" href="#_9-2-官方参考" aria-label="Permalink to &quot;9.2 官方参考&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/smac/configuring-smac-2d.html" target="_blank" rel="noreferrer">Nav2 Smac 2D Planner 配置</a></p><p><a href="https://docs.nav2.org/configuration/packages/smac/configuring-smac-hybrid.html" target="_blank" rel="noreferrer">Nav2 Smac Hybrid-A* Planner 配置</a></p><p><a href="https://docs.nav2.org/configuration/packages/smac/configuring-smac-lattice.html" target="_blank" rel="noreferrer">Nav2 Smac State Lattice Planner 配置</a></p>`,67)])])}const g=e(h,[["render",d]]);export{f as __pageData,g as default};
